SELECT CAST(DATE_FORMAT(CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE), '%Y-%m-01') AS DATE) AS month, AVG(DATEDIFF(CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE), CAST(s.shipped_at_utc + INTERVAL 6 HOUR AS DATE))) FROM shipments s JOIN orders o ON o.order_id = s.order_id WHERE s.status = 'delivered' AND NOT o.is_deleted AND CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE) BETWEEN DATE '2025-07-01' AND DATE '2026-06-30' GROUP BY 1 ORDER BY 1
